SET disabled_optimizers TO 'build_side_probe_side';
EXPLAIN SELECT p.a, b.c
FROM residual_empty_probe p
LEFT JOIN residual_empty_build b ON p.a = b.a AND p.payload > 0
ORDER BY ALL;
