ORDER BY ALL;
CREATE TABLE l(k INTEGER, v INTEGER);
CREATE TABLE r(k INTEGER, v INTEGER);
INSERT INTO l VALUES
    (1, 1),
    (-1, 5),
    (2, 1);
INSERT INTO r VALUES
     (1, 5),
     (-1, 0),
     (1, 1);
SELECT *
FROM l ANTI JOIN r
  ON l.k = r.k
 AND l.v + r.v > 2
ORDER BY k;
SELECT *
FROM l SEMI JOIN r
  ON l.k = r.k
 AND l.v + r.v > 2
ORDER BY k;

