CREATE TABLE nullable_strings AS
SELECT CASE range // 2048
    WHEN 0 THEN CASE WHEN range % 2 = 0 THEN NULL ELSE 'a' END
    WHEN 1 THEN CASE WHEN range % 2 = 0 THEN 'a' ELSE 'b' END
    WHEN 2 THEN 'z'
    ELSE 'c'
END AS s, 1 AS payload
FROM range(8192);
