CREATE VIEW nested_walk AS
SELECT *
FROM (
    SELECT o.id, o.selected, q.x
    FROM person o,
    LATERAL (
        SELECT r.x
        FROM person i,
        LATERAL (
            WITH RECURSIVE walk(x) USING KEY(x) AS (
                SELECT i.id
                UNION
                SELECT w.x + 1
                FROM walk w
                WHERE w.x < i.id + 2
                  AND NOT EXISTS (
                      SELECT 1
                      FROM recurring.walk visited
                      WHERE visited.x = w.x + 1
                  )
            )
            SELECT max(x) AS x FROM walk
        ) r
        WHERE i.id = o.id
        UNION ALL
        SELECT -1
    ) q
) result
;
