	(1, 'a', 3, false),
	(1, 'b', 4, true),
	(1, 'a', 5, false),
	(2, 'z', 1, true),
	(2, 'y', 2, true),
	(3, NULL, 1, true),
	(3, 'q', 2, false);
SELECT g, mode(v ORDER BY ord), mode(v ORDER BY ord DESC)
FROM mode_rewrite
GROUP BY g
ORDER BY g;
SELECT g, mode(v) FILTER (WHERE keep)
FROM mode_rewrite
WHERE g <> 2
GROUP BY g
ORDER BY g;
SELECT mode(v) IN ('y', 'z'), count(*)
FROM mode_rewrite
WHERE g = 2;
SELECT mode(DISTINCT v ORDER BY v), mode(DISTINCT v ORDER BY v DESC)
FROM mode_rewrite
WHERE g = 1;
