CREATE TABLE tg AS
SELECT CASE WHEN range % 16 = 3 THEN NULL ELSE range END::INTEGER AS x, (range % 16)::INTEGER AS g
FROM range(10240);
SELECT count(*) FROM (SELECT g, min(x) AS m FROM tg GROUP BY g HAVING m IS NULL) sub;

